{"role":"rgon","entry":{"code":"import os\nimport sys\nimport subprocess\nfrom pathlib import Path\n\nBASE_DIR = Path(r\"C:\\Users\\sangi\\Downloads\\shin-agent\")\nDESKTOP = Path(r\"C:\\Users\\sangi\\Desktop\")\nBRIDGE_PY = BASE_DIR / \"rgon_telegram_bridge.py\"\nCLOUD_URL = \"https://sangill111157-byte.github.io/shin-agent/rgon_alpha_audience.html\"\n\n\ndef find_chrome():\n    for c in (\n        r\"C:\\Program Files\\Google\\Chrome\\Application\\chrome.exe\",\n        r\"C:\\Program Files (x86)\\Google\\Chrome\\Application\\chrome.exe\",\n        os.path.expandvars(r\"%LOCALAPPDATA%\\Google\\Chrome\\Application\\chrome.exe\"),\n    ):\n        if os.path.exists(c):\n            return c\n    return \"chrome.exe\"\n\n\ndef main():\n    chrome = find_chrome()\n\n    # 1. 바탕화면 바로가기 (.url 및 전용 앱 .lnk) 생성\n    url_file = DESKTOP / \"👑_RGON_독대실_대시보드.url\"\n    url_file.write_text(f\"[InternetShortcut]\\nURL={CLOUD_URL}\\n\", encoding=\"utf-8\")\n\n    lnk_path = DESKTOP / \"RGON 사령부 전용앱.lnk\"\n    ps_cmd = (\n        f'$s = (New-Object -ComObject WScript.Shell).CreateShortcut(\"{lnk_path}\"); '\n        f'$s.TargetPath = \"{chrome}\"; '\n        f'$s.Arguments = \"--app={CLOUD_URL}\"; '\n        f'$s.Save()'\n    )\n    subprocess.run([\"powershell\", \"-NoProfile\", \"-Command\", ps_cmd], capture_output=True)\n\n    # 2. 지금 즉시 PC 화면에 전용 대시보드 앱 띄우기!\n    try:\n        subprocess.Popen([chrome, f\"--app={CLOUD_URL}\", \"--window-size=1420,920\"])\n    except Exception:\n        pass\n\n    # 3. 기존 기억 저장소 / 마감 관련 파일 탐색\n    mem_files = []\n    for p in sorted(BASE_DIR.iterdir()):\n        low = p.name.lower()\n        if not low.startswith((\"omni_\", \"ahn_queue_\")):\n            if p.is_dir() or p.suffix.lower() in (\".json\", \".md\", \".py\", \".bat\"):\n                mem_files.append(f\"{'📂' if p.is_dir() else '📄'} {p.name}\")\n\n    msg = (\n        f\"👑 [PC 대시보드 전용 앱 오픈 & 기억 저장소 스캔 완료!]\\n\"\n        f\"🌐 직통 링크: {CLOUD_URL}\\n\"\n        f\"🖥️ 바탕화면 아이콘 생성 완료: [RGON 사령부 전용앱]\\n\\n\"\n        f\"🧠 [shin-agent 주요 폴더 및 기억 저장소 목록]\\n\"\n        + \"\\n\".join(mem_files[:35])\n    )\n    print(msg)\n    if BRIDGE_PY.exists():\n        subprocess.run([sys.executable, str(BRIDGE_PY), \"--send-text\", msg[:3500]], cwd=str(BASE_DIR))\n\n\nif __name__ == \"__main__\":\n    main()\nCopy","lang":"python","kind":"code","lines":67,"bytes":2369,"funcs":["find_chrome","main"],"funcCount":2,"tryCount":1,"hasEntry":true,"score":15,"blockCount":38,"hash":"2949216470","ts":1792674974281,"url":"https://www.genspark.ai/agents?id=71753d51-edb9-4651-9ea5-ef85fdd55530","title":"RGON 사령부 6대 청사 실전 브리핑 엔진 구축 승인","role":"rgon"}}